SRC = {'yinhongying': 'yin-A.txt', 'peizhigu': 'pz-A.txt'}
for k, s in S.items():
    t = open(SRC.get(k, k + '-A.txt')).read().split('\n')
    i = next(n for n, l in enumerate(t) if l.startswith('场景'))
    t[i] = s
    open(k + '-I.txt', 'w').write('\n'.join(t))
    print(k, 'ok')
